; Auto-generated by scripts/generate-palette-transitions.js from src/games/dk/palettes/.
; Do not edit by hand -- regenerate instead.
;
; Every palette has one fixed IIgs slot layout: the IIgs palette 0 slot that each of the 32 NES
; palette RAM entries ($3F00-$3F1F) is shown in.  The layouts are chosen together, so that the
; background groups that keep the same slots across the transitions don't need their tiles
; redrawn (a group whose slots change has to be recompiled with the new swizzle table).
;
; Requires: NES_ColorToIIgs_X, NES_SetPaletteMap, RefreshPPUAttributesL, PPU_MEM, SHR_PALETTES

; Swizzle tables, in the PALDATA segment (palettes.s)
PAL_TITLE_SCREEN_SWIZZLE EXT
PAL_25M_SWIZZLE EXT
PAL_75M_SWIZZLE EXT
PAL_100M_SWIZZLE EXT
PAL_100M_HAMMER_SWIZZLE EXT
PAL_100M_ENDING_SWIZZLE EXT

; The palette ids (PAL_*) and pinned slots (PAL_SLOT_*) are in pal_defs.s.

; Layouts (NES color -> [slots] per group; *reserved, ~shown as):
;   title_screen
;     BG0 $0F $2C $38 $12 -> [0,1,2,3]
;     BG1 $0F $27 $27 $27 -> [0,4,5,6]
;     BG2 $0F $30 $30 $30 -> [0,7,8,9]
;     BG3 $0F -- -- -- -> [0,7,10,11]
;     SP0 $0F $25 -- -- -> [0,10,0,0]
;     SP1 $0F -- -- -- -> [0,0,0,0]
;     SP2 $0F -- -- -- -> [0,0,0,0]
;     SP3 $0F -- -- -- -> [0,0,0,0]
;   25m
;     BG0 $0F $15 $2C $12 -> [0,1,2,3]
;     BG1 $0F $27 $02 $17 -> [0,4,5,6]
;     BG2 $0F $30 $36 $06 -> [0,7,8,9]
;     BG3 $0F $30 $2C $24 -> [0,7,10,11]
;     SP0 $0F $02 $36 $16 -> [0,5,8,12]
;     SP1 $0F $30 $27 $24 -> [0,7,4,11]
;     SP2 $0F $16 $30 $37 -> [0,12,7,13]
;     SP3 $0F $06 $27 $02 -> [0,9,4,5]
;   75m
;     BG0 $0F $15 $2C $06 -> [0,1,2,3]
;     BG1 $0F $30 $27 $16 -> [0,4,5,6]
;     BG2 $0F $30 $36 $06 -> [0,7,8,9]
;     BG3 $0F $30 $2C $24 -> [0,7,10,11]
;     SP0 $0F $02 $36 $16 -> [0,12,8,6]
;     SP1 $0F $30 $27 $24 -> [0,4,5,11]
;     SP2 $0F $16 $30 $37 -> [0,6,4,13]
;     SP3 $0F $12 $37 $15 -> [0,14,13,1]
;   100m
;     BG0 $0F $2C $27 $02 -> [0,1,2,3]
;     BG1 $0F $30 $12 $24 -> [0,4,5,6]
;     BG2 $0F $30 $36 $06 -> [0,7,8,9]
;     BG3 $0F $30 $2C $24 -> [0,7,10,11]
;     SP0 $0F $02 $36 $16 -> [0,3,8,12]
;     SP1 $0F $30 $27 $24 -> [0,4,2,6]
;     SP2 $0F $16 $30 $37 -> [0,12,4,13]
;     SP3 $0F $06 $30 $12 -> [0,9,4,5]
;   100m_hammer
;     BG0 $0F $2C $27 $02 -> [0,1,2,3]
;     BG1 $0F $30 $12 $24 -> [0,4,5,6]
;     BG2 $0F $30 $36 $06 -> [0,7,8,9]
;     BG3 $0F $30 $2C $24 -> [0,7,10,11]
;     SP0 $0F $02 $36 $16 -> [0,3,8,12]
;     SP1 $0F $30 $27 $24 -> [0,4,2,6]
;     SP2 $0F $2C $16 $13 -> [0,1,12,13]
;     SP3 $0F $06 $30 $12 -> [0,9,4,5]
;   100m_ending
;     BG0 $0F $2C $27 $02 -> [0,1,2,3]
;     BG1 $0F $30 $12 $24 -> [0,4,5,6]
;     BG2 $0F $30 $36 $06 -> [0,7,8,9]
;     BG3 $0F $30 $2C $24 -> [0,7,10,11]
;     SP0 $0F $02 $36 $16 -> [0,3,8,12]
;     SP1 $0F $30 $27 $24 -> [0,4,2,6]
;     SP2 $0F -- -- -- -> [0,0,0,0]
;     SP3 $0F $30 $36 $06 -> [0,4,8,9]

            mx    %00

; UpdatePalette
;
; X = from palette id (PAL_*, or 0 for none), Y = to palette id
;
; Switches the swizzle tables to the new palette, loads its colors (LoadPaletteColors), then redraws
; the background groups whose slots changed.  Call from the GS task (it redraws tiles).
UpdatePalette
            lda   BG_UPDATE_MASKS,x
            pha
            lda   (1,s),y
            sta   1,s                 ; 1,s = groups to redraw

            phy
            ldx   PAL_SWIZZLE_LO,y
            lda   PAL_SWIZZLE_HI,y
            jsr   NES_SetPaletteMap
            ply

            jsr   LoadPaletteColors
            pla
            jsl   RefreshPPUAttributesL   ; (in the engine bank: ppu_entry.s)
            rts

; LoadPaletteColors
;
; Y = palette id.  Loads IIgs palette 0 from the current NES palette RAM, in the palette's layout,
; so the colors the game changes on the fly (fades, color cycling, ...) are shown too.  Slot 0 (the
; universal background color) is left alone: the game's $3F00 writes set it directly.
LoadPaletteColors
            lda   PAL_CELLS,y
            pha                       ; 1,s = slot map
            ldy   #31                 ; Backwards, so the BG colors win a shared slot
:loop       lda   (1,s),y
            and   #$00FF
            cmp   #$00FF
            beq   :next               ; not shown
            pha                       ; 1,s = slot * 2
            tyx
            ldal  PPU_MEM+$3F00,x
            jsr   NES_ColorToIIgs_X
            plx
            stal  SHR_PALETTES,x
:next       dey
            bpl   :loop
            pla
            rts

; DetectNESPalette
;
; X = the current palette id (0 = none).  Returns A = Y = the PAL_* id of the palette whose
; colors 1-3 are all in palette RAM (other than the reserved ones), or 0 if there is none (e.g. a
; step of a fade).  The current palette is tried first,
; then the palettes that follow it in the transitions, then the rest.
DetectNESPalette
            php
            rep   #$30
            stx   :from
            txa
            beq   :all
            jsr   :match              ; still the current palette?
            bcs   :found
            ldx   :from
            lda   PAL_SUCC,x          ; its successors, a 0-terminated list of ids
:snext      sta   :ptr
            tax
            lda:  0,x
            beq   :all
            tax
            jsr   :match
            bcs   :found
            lda   :ptr
            inc
            inc
            bra   :snext
:all        ldx   #2
:anext      jsr   :match
            bcs   :found
            inx
            inx
            cpx   #14
            bcc   :anext
            ldx   #0
:found      txy
            plp
            tya
            rts

; X = palette id.  Carry set if its colors are in palette RAM.  X is kept.  Only colors 1-3 of
; each group are compared (24 at most): color 0 is always IIgs slot 0.  One pass per group, from
; SP3 back to BG0, with its three colors compared inline.  NES colors are $00-$3F, so the $FF of a
; reserved or unused color is the only table byte with bit 7 set, and bmi skips it.
:match      phx
            lda   PAL_MATCH,x
            clc
            adc   #21
            tay                       ; Y -> the last group's 3 bytes
            ldx   #28                 ; X = the last group's palette RAM offset
            sep   #$20
            mx    %10
:group      lda:  0,y                 ; color 1
            bmi   *+8                 ; $FF = any value
            cmpl  PPU_MEM+$3F01,x
            bne   :mfail
            lda:  1,y                 ; color 2
            bmi   *+8
            cmpl  PPU_MEM+$3F02,x
            bne   :mfail
            lda:  2,y                 ; color 3
            bmi   *+8
            cmpl  PPU_MEM+$3F03,x
            bne   :mfail
            dey
            dey
            dey
            dex
            dex
            dex
            dex
            bpl   :group
            rep   #$20
            mx    %00
            plx
            sec
            rts
:mfail      rep   #$20
            plx
            clc
            rts

:from       ds    2
:ptr        ds    2

; id -> colors 1-3 of each group to match (BG0-BG3, SP0-SP3; $FF = any value: reserved or unused)
PAL_MATCH
            dw    0
            dw    PAL_TITLE_SCREEN_MATCH
            dw    PAL_25M_MATCH
            dw    PAL_75M_MATCH
            dw    PAL_100M_MATCH
            dw    PAL_100M_HAMMER_MATCH
            dw    PAL_100M_ENDING_MATCH
PAL_TITLE_SCREEN_MATCH
            db    $2C,$38,$12,$27,$27,$27,$30,$30,$30,$FF,$FF,$FF   ; BG0-BG3
            db    $25,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF   ; SP0-SP3
PAL_25M_MATCH
            db    $15,$2C,$12,$27,$02,$17,$30,$36,$06,$30,$2C,$24   ; BG0-BG3
            db    $02,$36,$16,$30,$27,$24,$16,$30,$37,$06,$27,$02   ; SP0-SP3
PAL_75M_MATCH
            db    $15,$2C,$06,$30,$27,$16,$30,$36,$06,$30,$2C,$24   ; BG0-BG3
            db    $02,$36,$16,$30,$27,$24,$16,$30,$37,$12,$37,$15   ; SP0-SP3
PAL_100M_MATCH
            db    $2C,$27,$02,$30,$12,$24,$30,$36,$06,$30,$2C,$24   ; BG0-BG3
            db    $02,$36,$16,$30,$27,$24,$16,$30,$37,$06,$30,$12   ; SP0-SP3
PAL_100M_HAMMER_MATCH
            db    $2C,$27,$02,$30,$12,$24,$30,$36,$06,$30,$2C,$24   ; BG0-BG3
            db    $02,$36,$16,$30,$27,$24,$2C,$16,$13,$06,$30,$12   ; SP0-SP3
PAL_100M_ENDING_MATCH
            db    $2C,$27,$02,$30,$12,$24,$30,$36,$06,$30,$2C,$24   ; BG0-BG3
            db    $02,$36,$16,$30,$27,$24,$FF,$FF,$FF,$30,$36,$06   ; SP0-SP3

; id -> the ids of the palettes that can follow it (transitions), 0-terminated
PAL_SUCC
            dw    PAL_NONE_SUCC
            dw    PAL_TITLE_SCREEN_SUCC
            dw    PAL_25M_SUCC
            dw    PAL_75M_SUCC
            dw    PAL_100M_SUCC
            dw    PAL_100M_HAMMER_SUCC
            dw    PAL_100M_ENDING_SUCC
PAL_NONE_SUCC
            dw    0
PAL_TITLE_SCREEN_SUCC
            dw    PAL_25M,0
PAL_25M_SUCC
            dw    PAL_75M,PAL_TITLE_SCREEN,0
PAL_75M_SUCC
            dw    PAL_100M,PAL_TITLE_SCREEN,0
PAL_100M_SUCC
            dw    PAL_100M_HAMMER,PAL_100M_ENDING,PAL_25M,PAL_TITLE_SCREEN,0
PAL_100M_HAMMER_SUCC
            dw    PAL_100M,PAL_100M_ENDING,PAL_25M,PAL_TITLE_SCREEN,0
PAL_100M_ENDING_SUCC
            dw    PAL_25M,PAL_100M,PAL_TITLE_SCREEN,0

; id -> swizzle tables (PALDATA segment, palettes.s)
PAL_SWIZZLE_LO
            dw    0
            dw    PAL_TITLE_SCREEN_SWIZZLE
            dw    PAL_25M_SWIZZLE
            dw    PAL_75M_SWIZZLE
            dw    PAL_100M_SWIZZLE
            dw    PAL_100M_HAMMER_SWIZZLE
            dw    PAL_100M_ENDING_SWIZZLE
PAL_SWIZZLE_HI
            dw    0
            dw    ^PAL_TITLE_SCREEN_SWIZZLE
            dw    ^PAL_25M_SWIZZLE
            dw    ^PAL_75M_SWIZZLE
            dw    ^PAL_100M_SWIZZLE
            dw    ^PAL_100M_HAMMER_SWIZZLE
            dw    ^PAL_100M_ENDING_SWIZZLE

; id -> slot map: for each NES palette RAM entry, the IIgs slot * 2, or $FF if it isn't loaded
; (color 0, which the game writes straight to slot 0, colors that share slot 0 with it, and
; approximated colors, which are shown in another color's slot)
PAL_CELLS
            dw    0
            dw    PAL_TITLE_SCREEN_CELLS
            dw    PAL_25M_CELLS
            dw    PAL_75M_CELLS
            dw    PAL_100M_CELLS
            dw    PAL_100M_HAMMER_CELLS
            dw    PAL_100M_ENDING_CELLS
PAL_TITLE_SCREEN_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$12,$FF,$FF,$FF,$FF   ; BG0-BG3
            db    $FF,$14,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF   ; SP0-SP3
PAL_25M_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$12,$FF,$0E,$14,$16   ; BG0-BG3
            db    $FF,$0A,$10,$18,$FF,$0E,$08,$16,$FF,$18,$0E,$1A,$FF,$12,$08,$0A   ; SP0-SP3
PAL_75M_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$12,$FF,$0E,$14,$16   ; BG0-BG3
            db    $FF,$18,$10,$0C,$FF,$08,$0A,$16,$FF,$0C,$08,$1A,$FF,$1C,$1A,$02   ; SP0-SP3
PAL_100M_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$12,$FF,$0E,$14,$16   ; BG0-BG3
            db    $FF,$06,$10,$18,$FF,$08,$04,$0C,$FF,$18,$08,$1A,$FF,$12,$08,$0A   ; SP0-SP3
PAL_100M_HAMMER_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$12,$FF,$0E,$14,$16   ; BG0-BG3
            db    $FF,$06,$10,$18,$FF,$08,$04,$0C,$FF,$02,$18,$1A,$FF,$12,$08,$0A   ; SP0-SP3
PAL_100M_ENDING_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$12,$FF,$0E,$14,$16   ; BG0-BG3
            db    $FF,$06,$10,$18,$FF,$08,$04,$0C,$FF,$FF,$FF,$FF,$FF,$08,$10,$12   ; SP0-SP3

