            dw    BG_UPDATE_MASKS_TITLE_SCREEN
            dw    BG_UPDATE_MASKS_25M
            dw    BG_UPDATE_MASKS_75M
            dw    BG_UPDATE_MASKS_100M
            dw    BG_UPDATE_MASKS_100M_HAMMER
